frappe.ui.form.on('Work Order', {
    sales_order: fetch_so_item_data,
    production_item: fetch_so_item_data
});

function fetch_so_item_data(frm) {
    if (frm.doc.sales_order && frm.doc.production_item) {
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Sales Order",
                name: frm.doc.sales_order
            },
            callback: function(r) {
                if (r.message) {
                    const sales_order = r.message;

                    // ✅ Set process from Sales Order parent
                    if (sales_order.process) {
                        frm.set_value('custom_process', sales_order.process);
                        frm.set_value('custom_release_liner', sales_order.release_liner);
                        frm.set_value('custom_release_liner_gsm', sales_order.release_liner_gsm);
                    } else {
                        frm.set_value('custom_process', "");
                        frm.set_value('custom_release_liner', "");
                        frm.set_value('custom_release_liner_gsm', "");
                    }

                    // ✅ Match item_code and set fields from Sales Order Item
                    if (sales_order.items && sales_order.items.length > 0) {
                        let matching_item = sales_order.items.find(item => item.item_code === frm.doc.production_item);

                        if (matching_item) {
                            frm.set_value('so_mm', matching_item.custom_mm || 0);
                            frm.set_value('so_colour', matching_item.colour || "");
                            frm.set_value('so_rolls', matching_item.rolls || 0);
                            frm.set_value('so_winding', matching_item.winding || 0);
                            frm.set_value('qty', matching_item.qty || 1);
                        } else {
                            frappe.msgprint("Matching item not found in Sales Order.");
                        }
                    } else {
                        frappe.msgprint("No items found in this Sales Order.");
                    }
                }
            }
        });
    }
}

frappe.ui.form.on('Work Order', {
    onload: function(frm) {
        frm.set_query('production_item', () => {
            return {
                filters: {
                    'is_stock_item': 1,
                    'is_sales_item': 1,
                    'item_group': ['in', ['Finished Goods', 'Semi Finished Goods']] // Filters for both groups
                }
            };
        });
    }
});

frappe.ui.form.on('BOM Operation', {
    meter: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.custom_cost_per_meter && row.custom_per_mtr) {
            row.operating_cost = row.custom_cost_per_meter * row.custom_per_mtr;
            frm.refresh_field("operations");
        }
    },
    cost_per_meter: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.custom_cost_per_meter && row.custom_per_mtr) {
            row.operating_cost = row.custom_cost_per_meter * row.custom_per_mtr;
            frm.refresh_field("operations");
        }
    }
});

frappe.ui.form.on('Sales Order Item', {
    qty(frm, cdt, cdn) {
        calculate_rolls(frm, cdt, cdn);
    },
    winding(frm, cdt, cdn) {
        calculate_rolls(frm, cdt, cdn);
    }
});

function calculate_rolls(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const qty = flt(row.qty);
    const winding = flt(row.winding);

    if (winding > 0) {
        // 👇 show rolls with 2 decimal points
        const roll = flt(qty / winding, 2);
        frappe.model.set_value(cdt, cdn, 'roll', roll);
    } else {
        frappe.model.set_value(cdt, cdn, 'roll', 0.00);
    }
}

frappe.ui.form.on('Sales Invoice Item', {
    qty: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        // Define conversion factor (example: 1 Mtr = 0.006 Sq. Mtr)
        // You can modify this logic as needed per item or UOM
        let conversion_factor = 0;

        if (row.uom === "MTR" || row.uom === "Meter" || row.uom === "Meters") {
            conversion_factor = 0.006; // example value
        }

        // Optional: Set item-based conversion (override if needed)
        if (row.item_code === "G6305" || row.item_name.includes("Topline Tape")) {
            conversion_factor = 0.012;  // example for specific items
        }

        row.custom__square_meter = flt(row.qty * conversion_factor, 4);

        frm.refresh_field("items");
    }
});

frappe.ui.form.on("Stock Entry", {
    before_submit: function(frm) {
        if (frm.doc.purpose === "Material Transfer for Manufacture") {
            frm.doc.items.forEach(function(d) {
                if (d.item_code === "RM-GSM-W-01-G" && d.s_warehouse) {
                    
                    frappe.db.get_value("Item", d.item_code, "reuse_count")
                        .then(r => {
                            let count = r.message.reuse_count || 0;

                            if (count < 3) {
                                // Prevent stock reduction
                                frappe.msgprint({
                                    title: "Reusing RM-3",
                                    message: "RM-3 reused (No stock reduced). Count: " + (count + 1),
                                    indicator: "blue"
                                });
                                d.qty = 0;

                                // Update reuse counter
                                frappe.db.set_value("Item", d.item_code, "reuse_count", count + 1);

                            } else {
                                // 4th time: consume stock
                                frappe.msgprint({
                                    title: "RM-3 Damaged",
                                    message: "RM-3 stock reduced. Counter reset.",
                                    indicator: "red"
                                });
                                frappe.db.set_value("Item", d.item_code, "reuse_count", 0);
                            }
                        });
                }
            });
        }
    }
});

frappe.ui.form.on('Sales Person', {
    validate: function(frm) {
        if (!frm.doc.employee) return;

        return frappe.db.get_value('Sales Person',
            { employee: frm.doc.employee },
            'name'
        ).then(r => {
            if (r && r.name && r.name !== frm.doc.name) {
                frappe.msgprint(__('Another Sales Person exists with the same Employee ID.'));
                frappe.validated = false;
            }
        });
    }
});

frappe.ui.form.on("Sales Order Item", {
    uom: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        // Example conversion based on custom logic
        if (row.uom == "Millimeter") {
            row.conversion_factor = 0.001;  // 1000 mm = 1 meter
        }
        else if (row.uom == "Square Meter") {
            // Example: If width is fixed (say 1.5 meters)
          //  let item_width = 1.5; // or fetch from item master
            row.conversion_factor = 1;
        }
        else if (row.uom == "Meter") {
            row.conversion_factor = 1;
        }

        // Recalculate qty in stock uom
        row.stock_qty = row.qty * row.conversion_factor;
        frm.refresh_field("items");
    }
});

frappe.ui.form.on("Stock Entry Detail", {
    batch_no: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.batch_no) return;

        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Batch",
                filters: { name: row.batch_no },
                fieldname: ["reuse_count", "max_reuse"]
            },
            callback: function(r) {
                if (!r.message) return;

                let reuse_count = r.message.reuse_count || 0;
                let max_reuse = r.message.max_reuse || 5;

                if (reuse_count >= max_reuse) {
                    frappe.msgprint(
                        __("Batch {0} already used {1} times. Please select a NEW batch.",
                          [row.batch_no, reuse_count])
                    );
                    frappe.model.set_value(cdt, cdn, "batch_no", "");
                }
            }
        });
    }
});

frappe.ui.form.on("Stock Entry", {
    validate(frm) {
        if (frm.doc.stock_entry_type !== "Manufacture") return;
            let confirmation_needed = false;
             let confirmed_rows = [];
            
            frm.doc.items.forEach(row => {
                if (!row.batch_no) return;
                
                // ✅ Skip if already handled
               if (row.has_confirmed_reuse) return;

                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Batch",
                        filters: { name: row.batch_no },
                        fieldname: ["reuse_count", "max_reuse"]
                    },
                    async: false,
                    callback: function(r) {
                        if (!r.message) return;
                        
                        let reuse_count = r.message.reuse_count || 0;
                        let max_reuse = r.message.max_reuse || 5;

                          if (reuse_count + 1 === max_reuse) {
                            confirmation_needed = true;
                            frappe.validated = false;

                            frappe.confirm(
                                `Batch ${row.batch_no} reached max reuse (${max_reuse}).<br>
                                Do you want to extend reuse and continue?`,
                                () => {
                                // YES → extend reuse
                                frappe.model.set_value(row.doctype, row.name, "extend_reuse", 1);
                                frappe.model.set_value(row.doctype, row.name, "force_deduct", 0);
                                frappe.model.set_value(row.doctype, row.name, "has_confirmed_reuse", 1);
                                frm.save();
                            },
                            () => {
                                // NO → force deduction
                                frappe.model.set_value(row.doctype, row.name, "extend_reuse", 0);
                                frappe.model.set_value(row.doctype, row.name, "force_deduct", 1);
                                frappe.model.set_value(row.doctype, row.name, "has_confirmed_reuse", 1);
                                frm.save();
                            }
                            );
                        }
                    }
                });
            });
             if (confirmation_needed) frappe.validated = false;
        

     if (frm.doc.stock_entry_type === "Material Transfer for Manufacture") {
    frm.doc.items.forEach(row => {
        if (!row.batch_no) return;

        if (!row.release_paper_good && !row.discard_batch) {
            frappe.validated = false; // 🚨 stop submit

            frappe.confirm(
                `Flag is not checked for Batch ${row.batch_no}. Do you want to discard this batch?`,
                () => {
                    // ✅ YES → User confirmed discard
                    if (!row.discard_reason) {
                        frappe.prompt(
                            [
                                {
                                    label: 'Discard Reason',
                                    fieldname: 'custom_discard_reason',
                                    fieldtype: 'Small Text',
                                    reqd: 1
                                }
                            ],
                            function(values){
                                row.custom_discard_reason = values.custom_discard_reason;

                                frappe.call({
                                    method: "frappe.client.set_value",
                                    args: {
                                        doctype: "Batch",
                                        name: row.batch_no,
                                        fieldname: {
                                            disabled: 1,
                                            custom_discard_reason: values.custom_discard_reason
                                        }
                                    },
                                    callback: function() {
                                        row.discard_batch = 1;
                                        frappe.msgprint(
                                            `Batch ${row.batch_no} discarded and disabled.<br>
                                             Reason saved: <b>${values.custom_discard_reason}</b><br>
                                             Please add a new Release Paper batch.`
                                        );

                                        // ✅ Auto add new blank row for substitution
                                        let new_row = frm.add_child("items");
                                        new_row.item_code = row.item_code;
                                        new_row.qty = row.qty;
                                        new_row.uom = row.uom;
                                    new_row.conversion_factor = row.conversion_factor;
                                     new_row.transfer_qty = row.transfer_qty;
                                     new_row.s_warehouse = row.s_warehouse;
                                    new_row.t_warehouse = row.t_warehouse;
                                    new_row.basic_rate = row.basic_rate;
                                    new_row.use_serial_batch_fields = row.use_serial_batch_fields;
                                        
                                        
                                        frm.refresh_field("items");
                                    }
                                });
                            },
                            'Discard Reason'
                        );
                    }
                },
                () => {
                    frappe.msgprint(
                        `Please tick 'Release Paper is Good' for Batch ${row.batch_no} to continue.`
                    );
                    frm.refresh_field("items");
                }
            );
        }
    });
}


    }
});

frappe.ui.form.on("Stock Entry", {
    validate(frm) {
        // --- Manufacture reuse confirmation logic ---
        if (frm.doc.stock_entry_type === "Manufacture") {
            let confirmation_needed = false;

            frm.doc.items.forEach(row => {
                if (!row.batch_no) return;

                // Skip if already confirmed
                if (row.has_confirmed_reuse) return;

                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Batch",
                        filters: { name: row.batch_no },
                        fieldname: ["reuse_count", "max_reuse"]
                    },
                    async: false,
                    callback: function(r) {
                        if (!r.message) return;

                        let reuse_count = r.message.reuse_count || 0;
                        let max_reuse = r.message.max_reuse || 2;

                        // Prompt if reuse_count + 1 >= max_reuse
                        if (reuse_count + 1 >= max_reuse) {
                            confirmation_needed = true;
                            frappe.validated = false;

                            frappe.confirm(
                                `Batch ${row.batch_no} reuse count is ${reuse_count}. Max reuse is ${max_reuse}.<br>
                                Do you want to extend reuse and continue?`,
                                () => {
                                    // YES → extend reuse
                                    frappe.model.set_value(row.doctype, row.name, "extend_reuse", 1);
                                    frappe.model.set_value(row.doctype, row.name, "force_deduct", 0);
                                    frappe.model.set_value(row.doctype, row.name, "has_confirmed_reuse", 1);
                                    frm.save();
                                },
                                () => {
                                    // NO → force deduction
                                    frappe.model.set_value(row.doctype, row.name, "extend_reuse", 0);
                                    frappe.model.set_value(row.doctype, row.name, "force_deduct", 1);
                                    frappe.model.set_value(row.doctype, row.name, "has_confirmed_reuse", 1);
                                    frm.save();
                                }
                            );
                        }
                    }
                });
            });

            if (confirmation_needed) frappe.validated = false;
        }

        // --- Material Transfer for Manufacture discard batch logic ---
        if (frm.doc.stock_entry_type === "Material Transfer for Manufacture") {
            frm.doc.items.forEach(row => {
                if (!row.batch_no) return;

                if (!row.release_paper_good && !row.discard_batch) {
                    frappe.validated = false; // stop submit

                    frappe.confirm(
                        `Flag is not checked for Batch ${row.batch_no}. Do you want to discard this batch?`,
                        () => {
                            // YES → prompt discard reason if not provided
                            if (!row.discard_reason) {
                                frappe.prompt(
                                    [
                                        {
                                            label: 'Discard Reason',
                                            fieldname: 'custom_discard_reason',
                                            fieldtype: 'Small Text',
                                            reqd: 1
                                        }
                                    ],
                                    function(values){
                                        row.custom_discard_reason = values.custom_discard_reason;

                                        frappe.call({
                                            method: "frappe.client.set_value",
                                            args: {
                                                doctype: "Batch",
                                                name: row.batch_no,
                                                fieldname: {
                                                    disabled: 1,
                                                    custom_discard_reason: values.custom_discard_reason
                                                }
                                            },
                                            callback: function() {
                                                row.discard_batch = 1;
                                                frappe.msgprint(
                                                    `Batch ${row.batch_no} discarded and disabled.<br>
                                                     Reason saved: <b>${values.custom_discard_reason}</b><br>
                                                     Please add a new Release Paper batch.`
                                                );

                                                // Auto add new blank row for substitution
                                                let new_row = frm.add_child("items");
                                                new_row.item_code = row.item_code;
                                                new_row.qty = row.qty;
                                                new_row.uom = row.uom;
                                                new_row.conversion_factor = row.conversion_factor;
                                                new_row.transfer_qty = row.transfer_qty;
                                                new_row.s_warehouse = row.s_warehouse;
                                                new_row.t_warehouse = row.t_warehouse;
                                                new_row.basic_rate = row.basic_rate;
                                                new_row.use_serial_batch_fields = row.use_serial_batch_fields;

                                                frm.refresh_field("items");
                                            }
                                        });
                                    },
                                    'Discard Reason'
                                );
                            }
                        },
                        () => {
                            frappe.msgprint(
                                `Please tick 'Release Paper is Good' for Batch ${row.batch_no} to continue.`
                            );
                            frm.refresh_field("items");
                        }
                    );
                }
            });
        }
    }
});

frappe.ui.form.on("Job Card", {
