frappe.ui.form.on("Coating Machine Production Record", {
    quality_inspection: function(frm) {
        if (frm.doc.quality_inspection) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Quality Inspection",
                    name: frm.doc.quality_inspection
                },
                callback: function(r) {
                    if (r.message) {
                        // Loop through child table of Quality Inspection Readings
                        (r.message.readings || []).forEach(row => {
                            if (row.parameter == "Quilon Spec") {
                                frm.set_value("quilon_spec", row.reading_value);
                            }
                            if (row.parameter == "Adhesive Spec") {
                                frm.set_value("adhesive_spec", row.reading_value);
                            }
                        });
                    }
                }
            });
        }
    }
});

frappe.ui.form.on("Coating Machine Production Record", {
    work_order: function(frm) {
        if (frm.doc.work_order) {
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Work Order",
                    name: frm.doc.work_order
                },
                callback: function(r) {
                    if (r.message) {
                        let wo = r.message;

                        if (wo.custom_operation_type === "Coating") {
                            // Example: assuming Work Order Item table has batch_no
                            if (wo.items && wo.items.length > 0) {
                                frm.set_value("quilon_batch", wo.items[0].batch_no || "");
                                if (wo.items.length > 1) {
                                    frm.set_value("adhesive_batch", wo.items[1].batch_no || "");
                                }
                            }
                        }
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Coating Machine Production Record', {
    before_workflow_action: function(frm) {
        if(frm.workflow_action === "Direct Approve") {
            const gsm = frm.doc.adhesive_coating_gsm_actual || 0;
            if(gsm < 30 || gsm > 40) {
                frappe.throw(`Adhesive GSM (${gsm}) is outside the allowed range (30–40). You must send for approval instead of direct approve.`);
            }
        }
    }
});

frappe.ui.form.on("Batch", {
    refresh(frm) {
        frm.add_custom_button("Update Quilon Tank", function() {
            frappe.call({
                method: "batch.update_quilon_tank_manual", // Calls the Server Script
                args: { doc: frm.doc },
                freeze: true,
                freeze_message: "Updating Quilon Tank...",
                callback: function(r) {
                    if (r.message) {
                        frappe.msgprint(r.message);
                        frm.reload_doc();
                    } else {
                        frappe.msgprint("No response received.");
                    }
                }
            });
        });
    }
});

frappe.ui.form.on('Stock Entry', {

    // ---------------------------- ON LOAD ----------------------------
    onload: function(frm) {
        frm.set_df_property('custom_quilon_target_qty', 'hidden', 1);
    },

    // ---------------------------- REFRESH ----------------------------
    refresh: function(frm) {
    const user_roles = frappe.user_roles;
    const allowed_roles = ["Stock Manager", "System Manager"];  // FIXED ROLE NAMES
    const can_edit = user_roles.some(r => allowed_roles.includes(r));

    if (["Scrap"].includes(frm.doc.custom_quilon_type) || frm.doc.custom_expiry_reached) {
        if (!can_edit) {
            frm.set_read_only();
            frm.disable_save();

            // Prevent duplicate message
            if (!frm.doc.__lock_alert_shown) {
                frappe.msgprint("🔒 Scrap or Expired Quilon — only Stock Manager can approve or edit.");
                frm.doc.__lock_alert_shown = true;
            }

            frm.set_df_property("custom_scrap_remarks", "read_only", 0);
        }
    }
},

    // ---------------------------- QUILON TYPE CHANGE ----------------------------
    custom_quilon_type: async function(frm) {
        const qtype = frm.doc.custom_quilon_type;
        if (!qtype) return;

        // Auto set warehouse
        frm.set_value('custom_quilon_warehouse', 'Quilon Warehouses - JG');

        // Show/Hide Target Qty
        if (["New Refill", "Refill"].includes(qtype)) {
            frm.set_df_property('custom_quilon_target_qty', 'hidden', 0);
            if (!frm.doc.custom_quilon_target_qty) {
                frm.set_value('custom_quilon_target_qty', 12500);
            }
        } else {
            frm.set_df_property('custom_quilon_target_qty', 'hidden', 1);
            frm.set_value('custom_quilon_target_qty', null);
        }

        // Fetch current stock
        const r = await frappe.db.get_value("Bin", {
            warehouse: 'Quilon Warehouses - JG',
            item_code: "RM00061-2"
        }, "actual_qty");

        const current_qty = r.message ? r.message.actual_qty : 0;
        frm.set_value("custom_current_quilon_qty", current_qty);

        // If REFILL but tank empty → force new refill
        if (qtype === "Refill" && current_qty <= 0) {
            frappe.msgprint("⚠️ Quilon Tank is empty. Please create a New Refill first.");
            frm.set_value("custom_quilon_type", "New Refill");
            return;
        }

        // Reset item table
        frm.clear_table('items');
        let row = frm.add_child('items');

        row.item_code = "RM00061-2";
        const itemData = await frappe.db.get_value('Item', { name: 'RM00061-2' }, ['stock_uom', 'valuation_rate']);

        if (itemData.message) {
            row.stock_uom = itemData.message.stock_uom || 'Gram';
            row.uom = itemData.message.stock_uom || 'Gram';
            row.conversion_factor = 1;
            row.basic_rate = itemData.message.valuation_rate || 0;
        }

        const target_qty = frm.doc.custom_quilon_target_qty || 12500;
        let qty_to_set = 0;

        // ---------------------------- NEW REFILL ----------------------------
        if (qtype === "New Refill") {
            frm.set_value('from_warehouse', 'RM Warehouse - JG');
            frm.set_value('to_warehouse', 'Quilon Warehouses - JG');

            qty_to_set = target_qty;

            const today = frappe.datetime.nowdate();
            frm.set_value("custom_last_refill_date", today);
            frm.set_value("custom_expiry_date", frappe.datetime.add_days(today, 5));

            row.qty = qty_to_set;
            row.transfer_qty = qty_to_set;
        }

        // ---------------------------- REFILL ----------------------------
        else if (qtype === "Refill") {
            
            // SET WAREHOUSES FOR REFILL
frm.set_value('from_warehouse', 'RM Warehouse - JG');
frm.set_value('to_warehouse', 'Quilon Warehouses - JG');


            // GET LAST STOCK ENTRY NAME ONLY
            const last_entry_list = await frappe.db.get_list("Stock Entry", {
                filters: {
                    custom_quilon_warehouse: 'Quilon Warehouses - JG',
                    custom_quilon_type: ["in", ["New Refill", "Refill"]]
                },
                fields: ["name"],
                order_by: "creation desc",
                limit: 1
            });

            if (!last_entry_list.length) {
                frappe.throw("⚠️ Missing previous refill details. Please perform a New Refill first.");
            }

            // NOW READ FULL DOCUMENT (NO FIELD RESTRICTIONS)
            const last_entry = await frappe.db.get_doc("Stock Entry", last_entry_list[0].name);

            // RESTORE LAST USED TARGET QTY
