function split_all_production_rows(frm) {

    frm.ignore_serial_batch_dialog = true;

    let new_items = [];
    let split_occurred = false;

    (frm.doc.items || []).forEach(item => {

        // ✅ UPDATED LOG ROLL LOGIC
        let is_log_roll =
    (
        item.item_code.includes("20 M") ||
        item.item_code.includes("25 M") ||
        item.item_code.includes("30 M") ||
        item.item_code.includes("50 M") ||
        item.item_code.includes("55 M") ||
        item.item_code.includes("100 M") ||
        item.item_code === "51300-1000-1000MM"   // ✅ NEW ITEM ADDED
    ) && item.qty > 1000;


        let is_cut_roll = (
            item.item_code.includes("10mm") ||
            item.item_code.includes("12mm") ||
            item.item_code.includes("15mm")
        ) && item.qty > 1;

        if (is_log_roll || is_cut_roll) {

            split_occurred = true;
            let split_qty = is_log_roll ? 1000 : 1;

            let total = item.qty;
            let count = Math.floor(total / split_qty);
            let remainder = total % split_qty;

            for (let i = 0; i < count; i++) {
                new_items.push({
                    item_code: item.item_code,
                    qty: split_qty,
                    uom: item.uom,
                    stock_uom: item.stock_uom,
                    conversion_factor: item.conversion_factor || 1,
                    s_warehouse: item.s_warehouse,
                    t_warehouse: item.t_warehouse,
                    is_finished_item: item.is_finished_item,
                    is_scrap_item: item.is_scrap_item
                });
            }

            if (remainder > 0) {
                new_items.push({
                    item_code: item.item_code,
                    qty: remainder,
                    uom: item.uom,
                    stock_uom: item.stock_uom,
                    conversion_factor: item.conversion_factor || 1,
                    s_warehouse: item.s_warehouse,
                    t_warehouse: item.t_warehouse
                });
            }

        } else {
            new_items.push(item);
        }
    });

    if (!split_occurred) return;

    frm.clear_table('items');

    new_items.forEach(d => {
        let row = frm.add_child('items');
        row.item_code = d.item_code;
        row.qty = d.qty;
        row.uom = d.uom;
        row.stock_uom = d.stock_uom;
        row.conversion_factor = d.conversion_factor;
        row.transfer_qty = d.qty;
        row.s_warehouse = d.s_warehouse;
        row.t_warehouse = d.t_warehouse;
    });

    frm.refresh_field('items');

    frm.ignore_serial_batch_dialog = true;

    frappe.msgprint({
        title: __('Success'),
        message: __('Split Complete. Mandatory fields populated. Please Save.'),
        indicator: 'green'
    });
}

