function calculate_wastage(frm) {

    let planned = flt(frm.doc.planned_qty);
    let produced = flt(frm.doc.fg_completed_qty);

    let cut_wastage = planned - produced;
    if (cut_wastage < 0) cut_wastage = 0;

    let log_roll_wastage = cut_wastage / planned;

    frm.set_value("actual_produced_qty", produced);
    frm.set_value("wastage_qty", cut_wastage);
    frm.set_value("wastage_log_roll_qty", log_roll_wastage);

    let rm = frm.doc.items.find(r => r.s_warehouse && r.batch_no);
    if (rm) frm.set_value("wastage_batch", rm.batch_no);
}

