function protect_and_calculate(frm) {

    // STEP 1: Lock consumed quantity
    let consumed = 0;

    frm.doc.items.forEach(row => {
        if (row.s_warehouse && row.qty) {
            if (!row.__fixed_qty) {
                row.__fixed_qty = row.qty;   // capture original qty
            } else {
                row.qty = row.__fixed_qty;  // restore it
            }
            consumed += row.qty;
        }
    });

    frm.refresh_field("items");

    // STEP 2: Calculate usage & wastage
    let planned = flt(frm.doc.planned_qty);
    let produced = flt(frm.doc.fg_completed_qty);

    if (!planned || !produced || !consumed) return;

    let used = (produced / planned) * consumed;
    let wastage = consumed - used;

    if (wastage < 0) wastage = 0;

    frm.set_value("used_log_roll_qty", used.toFixed(3));
    frm.set_value("wastage_log_roll_qty", wastage.toFixed(3));
}

