function fetch_purchase_receipt_details(frm) {
    if (frm.doc.reference_type === 'Purchase Receipt' && frm.doc.reference_name) {
        
        frappe.db.get_doc('Purchase Receipt', frm.doc.reference_name)
            .then(pr => {
                // 1. Fetch Supplier
                if (pr.supplier) {
                    frm.set_value('custom_supplier', pr.supplier);
                }
                
                // 2. Fetch Supplier Invoice No -> custom_invdcno_date_
                if (pr.custom_supplier_invoice_no) {
                    frm.set_value('custom_invdcno_date_', pr.custom_supplier_invoice_no); 
                }
                
                // 3. Fetch Supplier Delivery Note -> custom_grn_nodate
                if (pr.supplier_delivery_note) {
                    frm.set_value('custom_grn_nodate', pr.supplier_delivery_note);
                }
                
                // 4. Fetch Mode of Transport
                if (pr.mode_of_transport) {
                    frm.set_value('custom_mode_of_transport', pr.mode_of_transport);
                }
                
                // 5. Loop through PR items to match the Item Code and fetch Qty & PO
                if (frm.doc.item_code && pr.items) {
                    let matched_item = pr.items.find(row => row.item_code === frm.doc.item_code);
                    
                    if (matched_item) {
                        // Fetch the specific row quantity -> custom_invdc_qty
                        frm.set_value('custom_invdc_qty', matched_item.qty);
                        
                        // Fetch the Purchase Order number linked to this item row -> custom_po
                        if (matched_item.purchase_order) {
                            frm.set_value('custom_po', matched_item.purchase_order);
                        }
                    }
                }
            });
    }
}

