function check_and_fetch_pr_data(frm) {
    let ref_type = frm.doc.reference_type || (frappe.route_options && frappe.route_options.reference_type);
    let ref_name = frm.doc.reference_name || (frappe.route_options && frappe.route_options.reference_name);

    if (ref_type === 'Purchase Receipt' && ref_name) {
        fetch_purchase_receipt_details(frm);
    }
}

function fetch_purchase_receipt_details(frm) {
    let ref_name = frm.doc.reference_name || (frappe.route_options && frappe.route_options.reference_name);
    let current_item = frm.doc.item_code || (frappe.route_options && frappe.route_options.item_code);

    if (!ref_name) return;

    frappe.db.get_doc('Purchase Receipt', ref_name)
        .then(pr => {
            // Use frappe.model.set_value to force update the model layer directly
            frappe.model.set_value(frm.doctype, frm.docname, 'custom_supplier', pr.supplier);
            frappe.model.set_value(frm.doctype, frm.docname, 'custom_invdcno_date_', pr.custom_supplier_invoice_no);
            frappe.model.set_value(frm.doctype, frm.docname, 'custom_grn_nodate', pr.supplier_delivery_note);
            frappe.model.set_value(frm.doctype, frm.docname, 'custom_mode_of_transport', pr.mode_of_transport);
            
            if (current_item && pr.items) {
                let matched_item = pr.items.find(row => row.item_code === current_item);
                if (matched_item) {
                    frappe.model.set_value(frm.doctype, frm.docname, 'custom_invdc_qty', matched_item.qty);
                    frappe.model.set_value(frm.doctype, frm.docname, 'custom_po', matched_item.purchase_order);
                }
            }
            
            // Force rendering refresh on the UI fields
            frm.refresh_fields();
        });
}

