            fetch_template_from_item(frm);
        } else if (frm.doc.quality_inspection_template) {
            setTimeout(() => {
                correct_readings_table(frm);
            }, 800); 
        }
    }
});

// New logic to find the template name when ERPNext leaves the field blank
function fetch_template_from_item(frm) {
    if (!frm.doc.item_code) return;
    
    frappe.db.get_value('Item', frm.doc.item_code, 'quality_inspection_template')
        .then(r => {
            if (r && r.message && r.message.quality_inspection_template) {
                let template_name = r.message.quality_inspection_template;
                
                // Set the value programmatically without breaking the UI loops
                frm.doc.quality_inspection_template = template_name;
                frm.refresh_field('quality_inspection_template');
                
                // Now run our correction logic with the newly found template name
                correct_readings_table(frm);
            }
        });
}

function correct_readings_table(frm) {
    if (!frm.doc.quality_inspection_template) return;
    
    frappe.db.get_doc('Quality Inspection Template', frm.doc.quality_inspection_template)
        .then(template => {
            let params = template.item_quality_inspection_parameter;
            if (!params || params.length === 0) return;

            if (!frm.doc.readings || frm.doc.readings.length === 0) {
                frm.clear_table('readings');
                params.forEach(p => {
                    let child = frm.add_child('readings');
                    assign_row_data(child, p);
                });
            } else {
                frm.doc.readings.forEach((row, idx) => {
                    if (params[idx]) {
                        assign_row_data(row, params[idx]);
                        
                        let grid_row = frm.fields_dict.readings.grid.grid_rows[idx];
                        if (grid_row) {
                            grid_row.doc.characteristics = params[idx].specification;
                            grid_row.doc.specification = params[idx].custom_characteristics;
                            grid_row.doc.checking_method = params[idx].custom_checking_method;
                            grid_row.refresh();
                        }
                    }
                });
            }
            frm.refresh_field('readings');
        });
}

function assign_row_data(target_row, source_param) {
    target_row.characteristics = source_param.specification;
    target_row.specification = source_param.custom_characteristics;
    target_row.checking_method = source_param.custom_checking_method;
    
    target_row.numeric = source_param.numeric;
    target_row.min_value = source_param.min_value;
    target_row.max_value = source_param.max_value;
    target_row.value = source_param.value;
}

frappe.ui.form.on("Stock Entry", {
    refresh(frm) {

        if (frm.doc.docstatus !== 0) return;
        if (frm.doc.purpose !== "Manufacture") return;
        if (!frm.doc.work_order) return;

        // Don't show button if inspection already linked
        if (frm.doc.custom_in_process_inspection) return;

        let finished_item = frm.doc.items.find(d => d.is_finished_item);

        if (!finished_item) return;

        frappe.db.get_value(
            "Item",
            finished_item.item_code,
            "in_process_inspection_required"
        ).then(r => {

            if (!r.message || !r.message.in_process_inspection_required) {
                return;
            }

            frm.add_custom_button(__("Create In Process Inspection"), function () {

                // Fetch the latest submitted Job Card for this Work Order
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Job Card",
                        filters: {
                            work_order: frm.doc.work_order,
                            docstatus: 1
                        },
                        fields: ["name"],
                        order_by: "creation desc",
                        limit_page_length: 1
                    },
                    callback: function(res) {

                        let job_card = "";

                        if (res.message && res.message.length > 0) {
                            job_card = res.message[0].name;
                        }

                        frappe.new_doc("In Process Inspection Report", {

                            manufacturing_stock_entry: frm.doc.name,

                            work_order: frm.doc.work_order,

                            job_card: job_card,

                            article_no: finished_item.item_code,

                            article_name: finished_item.item_name,

                            operator_name: frappe.session.user,

                            inspection_date: frappe.datetime.get_today()

                        });

                    }
                });

            });

        });

    }
});

